				  const seconds = Math.max(0, Math.round(((typeof now === 'number' ? now : Date.now()) - ts) / 1000))
				  if (seconds < 60) return `${seconds} \u79d2\u524d`
				  if (seconds < 3600) return `${Math.floor(seconds / 60)} \u5206\u949f\u524d`
