				    if (latest !== '') return `\u5df2\u662f\u6700\u65b0\u7248\u672c ${current}\uff08\u6e90\u4e0a\u6700\u65b0 ${latest}\uff09`
				    if (error !== '') return `\u68c0\u67e5\u5931\u8d25\uff1a${error}`
				    if (checkable !== true) return `\u4e3b\u673a\u4fa7\u5173\u95ed\u4e86\u8054\u7f51\u68c0\u67e5\uff08\u5f53\u524d ${current}\uff09\u2014\u2014 \u7528\u53f3\u8fb9\u7684\u6309\u94ae\u53bb\u53d1\u5e03\u9875\u770b`
				    return `\u68c0\u67e5\u8fd9\u4e2a\u63d2\u4ef6\u81ea\u5df1\u6709\u6ca1\u6709\u65b0\u7248\u672c\uff08\u5f53\u524d ${current}\uff09`
